_SETUP_SPLASH_FRAMES_CACHE: dict[str, tuple[str, ...]] = {}


def load_setup_splash_frames(variant_name: str) -> tuple[str, ...]:
    if variant_name in _SETUP_SPLASH_FRAMES_CACHE:
        return _SETUP_SPLASH_FRAMES_CACHE[variant_name]

    if variant_name not in _SETUP_SPLASH_FRAMES_GZIP_B85_BY_VARIANT:
        raise KeyError(f"Unknown setup splash variant '{variant_name}'.")

    encoded_payload = _SETUP_SPLASH_FRAMES_GZIP_B85_BY_VARIANT[variant_name]
    compressed_payload = base64.b85decode(
        encoded_payload.replace("\n", "").encode("ascii")
    )
    raw_payload = gzip.decompress(compressed_payload)
    decoded_payload = json.loads(raw_payload.decode("utf-8"))

    if not isinstance(decoded_payload, list):
        raise ValueError("Invalid setup splash frame payload type.")

    parsed_frames: list[str] = []
    for frame in decoded_payload:
        if not isinstance(frame, str):
            raise ValueError("Invalid setup splash frame payload item.")
        # Support payloads serialized with literal "\\x1b" sequences.
        parsed_frames.append(frame.replace("\\x1b", "\x1b"))

    frame_tuple = tuple(parsed_frames)
    _SETUP_SPLASH_FRAMES_CACHE[variant_name] = frame_tuple
    return frame_tuple
